class Solution:
    def cloneGraph(self, node: Optional['Node']) -> Optional['Node']:
        if node is None:
            return None
        copies = {}

        def dfs(cur):
            if cur in copies:
                return copies[cur]
            clone = Node(cur.val)
            copies[cur] = clone
            for nb in cur.neighbors:
                clone.neighbors.append(dfs(nb))
            return clone

        return dfs(node)
